/// Raven `PM_SaberInTransition`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:1610-1617`
pub fn PM_SaberInTransition(r#move: c_int) -> qboolean {
    if r#move >= LS_T1_BR__R && r#move <= LS_T1_BL__L {
        return 1;
    }
    0
}

/// Raven `BG_SaberInTransitionAny`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:1619-1634`
pub fn BG_SaberInTransitionAny(r#move: c_int) -> qboolean {
    if PM_SaberInStart(r#move) != 0 {
        return 1;
    } else if PM_SaberInTransition(r#move) != 0 {
        return 1;
    } else if PM_SaberInReturn(r#move) != 0 {
        return 1;
    }
    0
}

/// Raven `BG_FlipPart`.
///
/// Source: `oracle/oracle/codemp/game/bg_panimate.c:1642-1666`
pub fn BG_FlipPart(ps: *mut playerState_t, part: c_int) {
    unsafe {
        if part == SETANIM_TORSO {
            (*ps).torsoFlip = if (*ps).torsoFlip != 0 { 0 } else { 1 };
        } else if part == SETANIM_LEGS {
            (*ps).legsFlip = if (*ps).legsFlip != 0 { 0 } else { 1 };
        }
    }
}

